local builder = luajava.bindClass("android.os.StrictMode$VmPolicy$Builder")()
StrictMode.setVmPolicy(builder.build())

local handler = Handler(Looper.getMainLooper())
local ctx = service

function hablar(texto)
  pcall(function() service.asyncSpeak(tostring(texto)) end)
end

function toast(msg)
  Toast.makeText(service, tostring(msg), Toast.LENGTH_SHORT).show()
end

local dlgPrincipal = nil

function crearDialogoPrincipal()
  if dlgPrincipal then return end
  dlgPrincipal = Dialog(service)
  local win = dlgPrincipal.getWindow()
  win.setType(WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY)
  win.setLayout(WindowManager.LayoutParams.MATCH_PARENT, WindowManager.LayoutParams.MATCH_PARENT)
  dlgPrincipal.setCancelable(false)
end

function mostrarPantalla(vista)
  crearDialogoPrincipal()
  dlgPrincipal.setContentView(vista)
  if not dlgPrincipal.isShowing() then dlgPrincipal.show() end
end

function cerrarComplemento()
  J.enMarcha = false
  motorApagar()
  bucleAmb = pararBucle(bucleAmb)
  bucleMenu = pararBucle(bucleMenu)
  if dlgPrincipal then pcall(function() dlgPrincipal.dismiss() end) end
  service.stopSelf()
end

