local function escribirArchivo(ruta, datos)
  local f = File(ruta)
  f.getParentFile().mkdirs()
  local out = FileOutputStream(f)
  out.write(datos)
  out.close()
end

function instalarSonidos()
  if File(dirBase .. "listo.txt").exists() then return end
  for nombre, b64 in pairs(SONIDOS) do
    escribirArchivo(dirSnd .. nombre .. ".mp3", Base64.decode(b64, Base64.DEFAULT))
  end
  escribirArchivo(dirBase .. "musica_menu.mp3", Base64.decode(MUSICA_MENU, Base64.DEFAULT))
  local fl = io.open(dirBase .. "listo.txt", "w")
  fl:write("1")
  fl:close()
end

function rutaSonido(nombre)
  return dirSnd .. nombre .. ".mp3"
end

function sonar(nombre)
  local ruta = rutaSonido(nombre)
  if not File(ruta).exists() then return end
  pcall(function()
    local mp = MediaPlayer()
    mp.setDataSource(ruta)
    mp.prepare()
    mp.start()
    mp.setOnCompletionListener(luajava.createProxy("android.media.MediaPlayer$OnCompletionListener", {
      onCompletion = function(m) pcall(function() m.release() end) end
    }))
  end)
end

function iniciarBucle(ruta, vol)
  local mp = nil
  pcall(function()
    mp = MediaPlayer()
    mp.setDataSource(ruta)
    mp.setLooping(true)
    mp.setVolume(vol or 1.0, vol or 1.0)
    mp.prepare()
    mp.start()
  end)
  return mp
end

function pararBucle(mp)
  if mp then pcall(function() mp.stop() mp.release() end) end
  return nil
end

local bucleMotor = nil
local bucleAmb = nil
local bucleMenu = nil

function motorPitch(factor)
  if bucleMotor then
    pcall(function()
      bucleMotor.setPlaybackParams(PlaybackParams().setSpeed(0.7 + factor * 0.9))
    end)
  end
end

function motorEncender()
  if bucleMotor or not J.vehiculo then return end
  local ruta = rutaSonido(J.vehiculo.motor)
  if not File(ruta).exists() then return end
  bucleMotor = iniciarBucle(ruta, 0.9)
  if bucleMotor then
    pcall(function() bucleMotor.setPlaybackParams(PlaybackParams().setSpeed(0.7)) end)
  end
end

function motorApagar()
  bucleMotor = pararBucle(bucleMotor)
end

function ambCambiar(nombre)
  if J.ambActual == nombre then return end
  J.ambActual = nombre
  bucleAmb = pararBucle(bucleAmb)
  local ruta = rutaSonido(nombre)
  if File(ruta).exists() then
    bucleAmb = iniciarBucle(ruta, 0.35)
  end
end

function musicaMenuIniciar()
  if bucleMenu then return end
  local ruta = dirBase .. "musica_menu.mp3"
  if File(ruta).exists() then
    bucleMenu = iniciarBucle(ruta, 0.8)
  end
end

function musicaMenuParar()
  bucleMenu = pararBucle(bucleMenu)
end

J = {
  mapa = "puerto_bravo",
  vehiculo = nil,
  x = 0, y = 0,
  dir = 0,
  vel = 0,
  acel = false, freno = false,
  gas = 50, dano = 0, dinero = 100,
  piloto = false, destino = nil,
  trabajo = nil,
  ayuda = nil,
  trafico = {},
  enMarcha = false,
  ambActual = "",
  sinGasAvisado = false,
  ultimoAvisoAyuda = 0,
}

function guardar()
  local ed = prefs.edit()
  ed.putInt("dinero", J.dinero)
  if J.vehiculo then ed.putString("vehiculo", J.vehiculo.id) end
  ed.apply()
end

function cargar()
  J.dinero = prefs.getInt("dinero", 100)
end

function mapaActual()
  for _, mp in ipairs(MAPAS) do
    if mp.id == J.mapa then return mp end
  end
  return MAPAS[1]
end

function esMar()
  return J.mapa == "mar"
end

function vehiculoPorId(id)
  for _, v in ipairs(VEHICULOS) do
    if v.id == id then return v end
  end
  return nil
end

function anchoMapa()
  local mp = mapaActual()
  if mp.ancho then return mp.ancho end
  return (mp.nav - 1) * 90
end

function altoMapa()
  local mp = mapaActual()
  if mp.alto then return mp.alto end
  return (mp.nc - 1) * 90
end

function esLibre()
  if not J.vehiculo then return false end
  return J.vehiculo.barco or J.vehiculo.vuela
end

function enCruce()
  if esLibre() or esMar() then return true end
  local rx = J.x % 90
  local ry = J.y % 90
  return (rx < 9 or rx > 81) and (ry < 9 or ry > 81)
end

function dist(ax, ay, bx, by)
  local dx = ax - bx
  local dy = ay - by
  return math.sqrt(dx * dx + dy * dy)
end

function avActual()
  return math.floor(J.x / 90 + 0.5)
end

function clActual()
  return math.floor(J.y / 90 + 0.5)
end

function nombreCalle()
  local mp = mapaActual()
  if esMar() then return "Mar de Poniente" end
  local av = mp.avenidas[avActual() + 1] or ""
  local cl = mp.calles[clActual() + 1] or ""
  return av .. " con " .. cl
end

function barrioActual()
  local mp = mapaActual()
  if esMar() then return { nombre = "Mar de Poniente", ambiente = "amb_mar" } end
  local a = avActual()
  local c = clActual()
  for _, b in ipairs(mp.barrios) do
    if a >= b.i0 and a <= b.i1 and c >= b.j0 and c <= b.j1 then return b end
  end
  return { nombre = mp.nombre, ambiente = "amb_ciudad" }
end

function lugarXY(l)
  if l.x then return l.x, l.y end
  return l.av * 90, l.cl * 90
end

function lugaresMapa(idMapa)
  local lista = {}
  for _, l in ipairs(LUGARES) do
    if l.mapa == idMapa then table.insert(lista, l) end
  end
  return lista
end

function buscarLugar(cond, idMapa)
  local mejor = nil
  local mejorD = 1e9
  for _, l in ipairs(LUGARES) do
    if (not idMapa or l.mapa == idMapa) and cond(l) then
      local lx, ly = lugarXY(l)
      local d = dist(J.x, J.y, lx, ly)
      if d < mejorD then mejorD = d mejor = l end
    end
  end
  return mejor, mejorD
end

function esGasolinera(l)
  return l.nombre:find("Gasolinera") ~= nil
end

function lugarAleatorio(idMapa)
  local lista = lugaresMapa(idMapa or J.mapa)
  if #lista == 0 then return nil end
  return lista[math.random(1, #lista)]
end

function trabajoNombre()
  local t = J.vehiculo and J.vehiculo.trabajo or nil
  if t == "taxi" then return "Taxista" end
  if t == "ambulancia" then return "Ambulancia" end
  if t == "vigilante" then return "Patrulla" end
  if t == "camion" then return "Camionero" end
  if t == "autobus" then return "Chofer de autobús" end
  if t == "bomberos" then return "Bombero" end
  if t == "grua" then return "Gruero" end
  if t == "helados" then return "Heladero" end
  if t == "paqueteria" then return "Repartidor" end
  if t == "mensajeria" then return "Mensajero" end
  return "Paseo libre"
end

function mostrarMenuPrincipal()
  J.enMarcha = false
  motorApagar()
  bucleAmb = pararBucle(bucleAmb)
  J.ambActual = ""
  musicaMenuIniciar()
  local layout = {
    LinearLayout,
    orientation = "vertical",
    layout_width = "fill",
    layout_height = "fill",
    padding = "16dp",
    {
      Button,
      text = "X",
      layout_width = "wrap",
      layout_height = "wrap",
      layout_marginBottom = "4dp",
      onClick = function() cerrarComplemento() end,
    },
    {
      TextView,
      text = "MUNDO ABIERTO CON CARROS",
      textSize = "26sp",
      gravity = "center",
      layout_width = "fill",
      layout_height = "wrap",
      layout_marginBottom = "4dp",
    },
    {
      TextView,
      text = "Elige tu vehículo para pasear por el mundo",
      textSize = "16sp",
      gravity = "center",
      layout_width = "fill",
      layout_height = "wrap",
      layout_marginBottom = "8dp",
    },
    {
      TextView,
      id = "txtDineroMenu",
      text = "Dinero: " .. J.dinero .. " pesos",
      textSize = "18sp",
      gravity = "center",
      layout_width = "fill",
      layout_height = "wrap",
      layout_marginBottom = "8dp",
    },
    {
      Button,
      text = "PROBAR SONIDO",
      layout_width = "fill",
      layout_height = "wrap",
      layout_marginBottom = "8dp",
      onClick = function()
        sonar("claxon")
        hablar("Probando sonido. Este es el juego Mundo Abierto con Carros.")
      end,
    },
  }
  for _, v in ipairs(VEHICULOS) do
    local trabajo = v.trabajo or "paseo"
    local kmh = math.floor(v.vel_max * 3.6 + 0.5)
    local vv = v
    table.insert(layout, {
      Button,
      text = vv.nombre .. "  |  " .. kmh .. " km/h  |  " .. trabajo,
      layout_width = "fill",
      layout_height = "wrap",
      layout_marginBottom = "4dp",
      onClick = function()
        elegirVehiculo(vv)
      end,
    })
  end
  local sv = ScrollView(service)
  sv.addView(loadlayout(layout))
  mostrarPantalla(sv)
  dlgPrincipal.setTitle("Mundo Abierto con Carros")
  hablar("Mundo Abierto con Carros. Elige tu vehículo.")
end

function elegirVehiculo(v)
  J.vehiculo = v
  J.dano = 0
  J.gas = 50
  J.vel = 0
  J.piloto = false
  J.destino = nil
  J.trabajo = nil
  J.ayuda = nil
  J.trafico = {}
  guardar()
  musicaMenuParar()
  if v.barco then
    J.mapa = "mar"
    J.x = 1200
    J.y = 1200
    J.dir = 0
  else
    J.mapa = "puerto_bravo"
    local mp = mapaActual()
    J.x = math.floor(mp.nav / 2) * 90
    J.y = math.floor(mp.nc / 2) * 90
    J.dir = 0
  end
  sonar("arranque")
  hablar("Elegiste " .. v.nombre .. ". " .. trabajoNombre() .. ". A manejar.")
  mostrarPantallaManejo()
end

local dm = service.getResources().getDisplayMetrics()
local ANCHO_PANTALLA = dm.widthPixels
local mapaBmp = nil
local mapaCanvas = nil
local pincelCalle = nil
local pincelFondo = nil
local pincelJugador = nil
local pincelDestino = nil
local pincelAyuda = nil
local pincelTrafico = nil
local pincelLugar = nil
local pincelGas = nil
local pincelTaller = nil

function crearPinceles()
  if pincelCalle then return end
  pincelFondo = Paint()
  pincelFondo.setColor(Color.rgb(20, 26, 20))
  pincelCalle = Paint()
  pincelCalle.setColor(Color.rgb(120, 120, 120))
  pincelCalle.setStrokeWidth(7)
  pincelJugador = Paint()
  pincelJugador.setColor(Color.rgb(60, 140, 255))
  pincelDestino = Paint()
  pincelDestino.setColor(Color.RED)
  pincelDestino.setStyle(Paint.Style.STROKE)
  pincelDestino.setStrokeWidth(5)
  pincelAyuda = Paint()
  pincelAyuda.setColor(Color.YELLOW)
  pincelTrafico = Paint()
  pincelTrafico.setColor(Color.WHITE)
  pincelLugar = Paint()
  pincelLugar.setColor(Color.rgb(200, 200, 200))
  pincelGas = Paint()
  pincelGas.setColor(Color.GREEN)
  pincelTaller = Paint()
  pincelTaller.setColor(Color.rgb(255, 140, 0))
end

function dibujarMapa()
  if not mapaCanvas or not imgMapa then return end
  crearPinceles()
  local W = mapaBmp.getWidth()
  local H = mapaBmp.getHeight()
  local escala = W / 540
  local ox = W / 2 - J.x * escala
  local oy = H / 2 - J.y * escala
  mapaCanvas.drawRect(0, 0, W, H, pincelFondo)
  local mp = mapaActual()
  if not esMar() then
    for i = 0, mp.nav - 1 do
      local x = i * 90 * escala + ox
      if x >= -10 and x <= W + 10 then
        mapaCanvas.drawLine(x, 0, x, H, pincelCalle)
      end
    end
    for j = 0, mp.nc - 1 do
      local y = j * 90 * escala + oy
      if y >= -10 and y <= H + 10 then
        mapaCanvas.drawLine(0, y, W, y, pincelCalle)
      end
    end
  end
  for _, l in ipairs(lugaresMapa(J.mapa)) do
    local lx, ly = lugarXY(l)
    local px = lx * escala + ox
    local py = ly * escala + oy
    if px >= 0 and px <= W and py >= 0 and py <= H then
      local p = pincelLugar
      if esGasolinera(l) then p = pincelGas
      elseif l.tipo == "taller" then p = pincelTaller end
      mapaCanvas.drawCircle(px, py, 7, p)
    end
  end
  if J.destino then
    local px = J.destino.x * escala + ox
    local py = J.destino.y * escala + oy
    local r = 16 + (os.time() % 2) * 8
    mapaCanvas.drawCircle(px, py, r, pincelDestino)
  end
  if J.ayuda then
    local px = J.ayuda.x * escala + ox
    local py = J.ayuda.y * escala + oy
    mapaCanvas.drawRect(px - 10, py - 10, px + 10, py + 10, pincelAyuda)
  end
  for _, t in ipairs(J.trafico) do
    local px = t.x * escala + ox
    local py = t.y * escala + oy
    if px >= 0 and px <= W and py >= 0 and py <= H then
      mapaCanvas.drawCircle(px, py, 6, pincelTrafico)
    end
  end
  local cx = W / 2
  local cy = H / 2
  local dx = 0
  local dy = 0
  if J.dir == 0 then dx = 1 elseif J.dir == 1 then dy = 1 elseif J.dir == 2 then dx = -1 else dy = -1 end
  mapaCanvas.drawCircle(cx, cy, 12, pincelJugador)
  mapaCanvas.drawLine(cx, cy, cx + dx * 22, cy + dy * 22, pincelJugador)
  imgMapa.invalidate()
end

