end

function girar(lado)
  if J.piloto then desactivarPiloto() end
  if not enCruce() then
    toast("Solo puedes girar en un cruce")
    return
  end
  J.dir = (J.dir + lado) % 4
  if J.dir < 0 then J.dir = J.dir + 4 end
  sonar("intermitente")
end

function actualizarHUD()
  if not txtVel then return end
  txtVel.setText(math.floor(J.vel * 3.6 + 0.5) .. " km/h")
  txtGas.setText("Gas: " .. math.floor(J.gas + 0.5) .. " L")
  txtDano.setText("Daño: " .. math.floor(J.dano + 0.5) .. "%")
  txtDinero.setText(J.dinero .. " $")
  local b = barrioActual()
  txtLugar.setText(mapaActual().nombre .. "  |  " .. nombreCalle() .. "  |  " .. b.nombre)
  if btnPiloto then
    if J.piloto then
      btnPiloto.setText("PILOTO: DESACTIVAR")
    else
      btnPiloto.setText("PILOTO AUTOMÁTICO")
    end
  end
end

function sembrarTrafico()
  J.trafico = {}
  if esMar() then return end
  local mp = mapaActual()
  for i = 1, 4 do
    local av = math.random(0, mp.nav - 1)
    local cl = math.random(0, mp.nc - 1)
    table.insert(J.trafico, {
      x = av * 90,
      y = cl * 90,
      dir = math.random(0, 3),
      vel = 6 + math.random(0, 6),
    })
  end
end

function cambiarMapa(idMapa)
  J.mapa = idMapa
  local mp = mapaActual()
  if esMar() then
    J.x = 1200
    J.y = 1200
  else
    J.x = math.floor(mp.nav / 2) * 90
    J.y = math.floor(mp.nc / 2) * 90
  end
  J.dir = 0
  J.vel = 0
  sembrarTrafico()
  ambCambiar(barrioActual().ambiente)
  hablar("Llegando a " .. mp.nombre)
end

function fijarDestino(dest)
  J.destino = dest
  if txtEstado then
    txtEstado.setText("Destino: " .. dest.nombre)
  end
  hablar("Destino: " .. dest.nombre .. ". Pulsa piloto automático para que te lleve.")
end

function activarPiloto()
  if not J.destino then
    toast("Primero elige un destino en el menú de destinos o busca trabajo")
    hablar("Primero elige un destino.")
    return
  end
  J.piloto = true
  sonar("menu_ok")
  hablar("Piloto automático activado. Te llevo a " .. J.destino.nombre)
end

function desactivarPiloto()
  if not J.piloto then return end
  J.piloto = false
  sonar("menu_atras")
  hablar("Piloto automático desactivado. Manejas tú.")
end

function alternarPiloto()
  if J.piloto then
    desactivarPiloto()
  else
    activarPiloto()
  end
end

function mover(dt)
  local v = J.vehiculo
  if not v then return end
  if J.dano >= 100 then
    J.vel = 0
    if not J.rotoAvisado then
      J.rotoAvisado = true
      hablar("El vehículo está destrozado. Llama a la grúa o al taller en el menú de ayuda.")
    end
    return
  end
  if J.gas <= 0 then
    J.vel = 0
    if not J.sinGasAvisado then
      J.sinGasAvisado = true
      hablar("Te quedaste sin gasolina. Pide ayuda en el menú de ayuda.")
    end
    return
  end
  if J.freno then
    if J.vel > 5 then sonar("frenazo") end
    J.vel = math.max(0, J.vel - v.freno * dt)
  elseif J.acel then
    J.vel = math.min(v.vel_max, J.vel + v.acel * dt)
  else
    J.vel = math.max(0, J.vel - 3.5 * dt)
  end
  if J.vel > 0 then
    local dx = 0
    local dy = 0
    if J.dir == 0 then dx = 1 elseif J.dir == 1 then dy = 1 elseif J.dir == 2 then dx = -1 else dy = -1 end
    J.x = J.x + dx * J.vel * dt
    J.y = J.y + dy * J.vel * dt
    J.gas = math.max(0, J.gas - J.vel * dt * 0.008)
    local ax = anchoMapa()
    local ay = altoMapa()
    if J.x < 0 then J.x = 0 choqueBorde() end
    if J.x > ax then J.x = ax choqueBorde() end
    if J.y < 0 then J.y = 0 choqueBorde() end
    if J.y > ay then J.y = ay choqueBorde() end
  end
  if J.vel > 0.5 or J.acel then
    motorEncender()
    motorPitch(J.vel / v.vel_max)
  else
    motorApagar()
  end
end

function choqueBorde()
  if J.vel > 8 then
    sonar("choque_leve")
    J.dano = math.min(100, J.dano + 5)
    J.vel = 0
    hablar("Chocaste con el borde.")
  end
end

function pilotoTick(dt)
  if not J.piloto or not J.destino then return end
  local d = J.destino
  if d.mapa ~= J.mapa then
    local salida = buscarLugar(function(l) return l.tipo == "salida" end, J.mapa)
    local tx, ty
    if salida then tx, ty = lugarXY(salida) else tx, ty = anchoMapa() / 2, altoMapa() / 2 end
    if dist(J.x, J.y, tx, ty) < 12 then
      cambiarMapa(d.mapa)
      return
    end
    pilotoHacia(tx, ty, dt)
    return
  end
  if dist(J.x, J.y, d.x, d.y) < 9 then
    J.vel = 0
    J.piloto = false
    motorApagar()
    sonar("llegada")
    hablar("Llegaste a " .. d.nombre)
    local accion = d.accion
    J.destino = nil
    if accion then accion() end
    return
  end
  pilotoHacia(d.x, d.y, dt)
end

function pilotoHacia(tx, ty, dt)
  local v = J.vehiculo
  local dx = tx - J.x
  local dy = ty - J.y
  local deseado = 0
  if math.abs(dx) > 10 then
    deseado = dx > 0 and 0 or 2
  elseif math.abs(dy) > 10 then
    deseado = dy > 0 and 1 or 3
  else
    deseado = J.dir
  end
  if deseado ~= J.dir and enCruce() then
    J.dir = deseado
  end
  local dd = dist(J.x, J.y, tx, ty)
  local vObj = math.min(v.vel_max * 0.55, 3 + dd * 0.25)
  if J.vel < vObj then
    J.vel = math.min(vObj, J.vel + v.acel * dt)
  else
    J.vel = math.max(vObj, J.vel - v.freno * dt)
  end
  local mx = 0
  local my = 0
  if J.dir == 0 then mx = 1 elseif J.dir == 1 then my = 1 elseif J.dir == 2 then mx = -1 else my = -1 end
  J.x = J.x + mx * J.vel * dt
  J.y = J.y + my * J.vel * dt
  J.gas = math.max(0, J.gas - J.vel * dt * 0.008)
  if J.vel > 0.5 then
    motorEncender()
    motorPitch(J.vel / v.vel_max)
  end
end

function traficoTick(dt)
  if esMar() then return end
  local mp = mapaActual()
  for _, t in ipairs(J.trafico) do
    local dx = 0
    local dy = 0
    if t.dir == 0 then dx = 1 elseif t.dir == 1 then dy = 1 elseif t.dir == 2 then dx = -1 else dy = -1 end
    t.x = t.x + dx * t.vel * dt
    t.y = t.y + dy * t.vel * dt
    if t.x < 0 or t.x > (mp.nav - 1) * 90 or t.y < 0 or t.y > (mp.nc - 1) * 90 then
      t.dir = (t.dir + 2) % 4
      t.x = math.max(0, math.min((mp.nav - 1) * 90, t.x))
      t.y = math.max(0, math.min((mp.nc - 1) * 90, t.y))
    end
    if (t.x % 90 < 4 or t.x % 90 > 86) and (t.y % 90 < 4 or t.y % 90 > 86) and math.random() < 0.02 then
      t.dir = math.random(0, 3)
    end
    if J.vel > 3 and dist(J.x, J.y, t.x, t.y) < 8 then
      local ahora = os.time()
      if not J.ultimoChoque or ahora - J.ultimoChoque >= 3 then
        J.ultimoChoque = ahora
        sonar("choque")
        J.dano = math.min(100, J.dano + 12)
        J.vel = J.vel * 0.3
        hablar("Chocaste con otro carro.")
      end
    end
  end
end

function ayudaTick(dt)
  local a = J.ayuda
  if not a then return end
  if a.estado == "viene" then
    local dx = J.x - a.x
    local dy = J.y - a.y
    local dd = dist(J.x, J.y, a.x, a.y)
    if dd < 20 then
      a.estado = "llego"
      sonar("llegada")
      aplicarAyuda(a.tipo)
      J.ayuda = nil
      return
    end
    local dirD = 0
    if math.abs(dx) > 10 then
      dirD = dx > 0 and 0 or 2
    elseif math.abs(dy) > 10 then
      dirD = dy > 0 and 1 or 3
    end
    a.dir = dirD
    local mx = 0
    local my = 0
    if dirD == 0 then mx = 1 elseif dirD == 1 then my = 1 elseif dirD == 2 then mx = -1 else my = -1 end
    a.x = a.x + mx * 16 * dt
    a.y = a.y + my * 16 * dt
    local ahora = os.time()
    if ahora - J.ultimoAvisoAyuda >= 8 then
      J.ultimoAvisoAyuda = ahora
      hablar("La ayuda está a " .. math.floor(dd + 0.5) .. " metros.")
    end
  end
end

function aplicarAyuda(tipo)
  if tipo == "ambulancia" then
    J.dano = math.max(0, J.dano - 50)
    sonar("curar")
    hablar("La ambulancia llegó y te atendió. Ya estás mejor.")
  elseif tipo == "grua" then
    local taller = buscarLugar(function(l) return l.tipo == "taller" end, J.mapa)
    if taller then
      local tx, ty = lugarXY(taller)
      J.x = tx
      J.y = ty
      J.vel = 0
    end
    J.dano = math.max(0, J.dano - 20)
    sonar("llegada")
    hablar("La grúa te llevó al taller. Aquí te lo reparan.")
  elseif tipo == "taller" then
    J.dano = 0
    J.rotoAvisado = false
    sonar("reparar")
    hablar("El mecánico llegó y reparó tu carro aquí mismo. Quedó como nuevo.")
  elseif tipo == "gasolina" then
    J.gas = 50
    J.sinGasAvisado = false
    sonar("repostar")
    hablar("El mecánico llegó con gasolina y te llenó el tanque.")
  end
  actualizarHUD()
end

function tick()
  if not J.enMarcha then J.tickCorre = false return end
  local dt = 0.15
  if J.piloto then
    pilotoTick(dt)
  else
    mover(dt)
  end
  traficoTick(dt)
  ayudaTick(dt)
  ambCambiar(barrioActual().ambiente)
  local gas, dg = buscarLugar(function(l) return esGasolinera(l) end, J.mapa)
  if gas and dg < 45 then
    local costo = math.ceil((50 - J.gas) * 1)
    btnGas.setText("REPOSTAR ($" .. costo .. ")")
    btnGas.setVisibility(View.VISIBLE)
  else
    btnGas.setVisibility(View.GONE)
  end
  local tal, dt2 = buscarLugar(function(l) return l.tipo == "taller" end, J.mapa)
  if tal and dt2 < 45 then
    btnTaller.setText("REPARAR ($20)")
    btnTaller.setVisibility(View.VISIBLE)
  else
    btnTaller.setVisibility(View.GONE)
  end
  if J.trabajo and J.trabajo.listo then
    btnAccion.setText(J.trabajo.accionTexto)
    btnAccion.setVisibility(View.VISIBLE)
  else
    btnAccion.setVisibility(View.GONE)
  end
  if J.trabajo and J.trabajo.objetivo then
    local o = J.trabajo.objetivo
    if o.mapa == J.mapa and dist(J.x, J.y, o.x, o.y) < 12 and J.vel < 2 then
      J.trabajo.listo = true
    end
  end
  actualizarHUD()
  dibujarMapa()
  handler.postDelayed(luajava.createProxy("java.lang.Runnable", { run = tick }), 150)
end

function lugarCercanoTipo(tipo)
  return buscarLugar(function(l) return l.tipo == tipo end, J.mapa)
end

function fijarObjetivoTrabajo(lugar, texto)
  local lx, ly = lugarXY(lugar)
  J.trabajo.objetivo = { mapa = lugar.mapa, x = lx, y = ly, nombre = lugar.nombre }
  J.trabajo.accionTexto = texto
  J.trabajo.listo = false
  fijarDestino({ mapa = lugar.mapa, x = lx, y = ly, nombre = lugar.nombre, accion = function()
    J.trabajo.listo = true
  end })
end

function buscarTrabajo()
  local t = J.vehiculo and J.vehiculo.trabajo or nil
  if not t then
    toast("Este vehículo no tiene trabajo, es solo para pasear")
    hablar("Este vehículo no tiene trabajo. Es solo para pasear por el mundo.")
    return
  end
  if J.trabajo then
    toast("Ya tienes un trabajo en curso")
    hablar("Ya tienes un trabajo en curso. Termínalo primero.")
    return
  end
  local rec = nil
  local ent = nil
  local paga = 20
  if t == "taxi" then
    rec = lugarAleatorio()
    ent = lugarAleatorio()
    paga = 25
  elseif t == "ambulancia" then
    rec = lugarAleatorio()
    ent = lugarCercanoTipo("hospital")
    paga = 30
  elseif t == "vigilante" then
    rec = lugarAleatorio()
    ent = lugarCercanoTipo("comisaria")
    paga = 35
  elseif t == "camion" then
    rec = buscarLugar(function(l) return l.tipo == "tienda" or l.tipo == "negocio" end, J.mapa) or lugarAleatorio()
    ent = lugarAleatorio()
    paga = 40
  elseif t == "grua" then
    rec = lugarAleatorio()
    ent = lugarCercanoTipo("taller")
    paga = 30
  elseif t == "paqueteria" then
    rec = buscarLugar(function(l) return l.tipo == "tienda" end, J.mapa) or lugarAleatorio()
    ent = lugarAleatorio()
    paga = 20
  elseif t == "mensajeria" then
    rec = buscarLugar(function(l) return l.tipo == "muelle" or l.tipo == "embarcadero" end, J.mapa) or lugarAleatorio()
    ent = buscarLugar(function(l) return l.tipo == "muelle" or l.tipo == "embarcadero" end, J.mapa) or lugarAleatorio()
    paga = 25
  elseif t == "bomberos" then
    rec = lugarAleatorio()
    paga = 35
  elseif t == "autobus" or t == "helados" then
    rec = lugarAleatorio()
    paga = 10
  end
  if not rec then
    toast("No hay trabajo aquí")
    return
  end
  J.trabajo = { tipo = t, fase = 1, paga = paga, paradas = 0 }
  if t == "autobus" then J.trabajo.paradas = 3 J.trabajo.pagaParada = 10 end
  if t == "helados" then J.trabajo.paradas = 3 J.trabajo.pagaParada = 8 end
  local textoRec = "RECOGER"
  if t == "taxi" then textoRec = "RECOGER AL PASAJERO"
  elseif t == "ambulancia" then textoRec = "RECOGER AL HERIDO"
  elseif t == "vigilante" then textoRec = "DETENER A LA PERSONA"
  elseif t == "camion" then textoRec = "CARGAR LA MERCANCÍA"
  elseif t == "grua" then textoRec = "ENGANCHAR EL CARRO"
  elseif t == "paqueteria" then textoRec = "RECOGER EL PAQUETE"
  elseif t == "mensajeria" then textoRec = "RECOGER EL ENVÍO"
  elseif t == "bomberos" then textoRec = "APAGAR EL FUEGO"
  elseif t == "autobus" then textoRec = "RECOGER PASAJEROS"
  elseif t == "helados" then textoRec = "VENDER HELADOS" end
  J.trabajo.entrega = ent
  J.trabajo.textoRec = textoRec
  fijarObjetivoTrabajo(rec, textoRec)
  sonar("notificacion")
  if t == "taxi" then hablar("Trabajo de taxista. Recoge al pasajero en " .. rec.nombre)
  elseif t == "ambulancia" then hablar("Hay un herido en " .. rec.nombre .. ". Ve a recogerlo.")
  elseif t == "vigilante" then hablar("Hay una persona haciendo cosas malas en " .. rec.nombre .. ". Ve a detenerla.")
  elseif t == "bomberos" then hablar("Hay un fuego en " .. rec.nombre .. ". Ve a apagarlo.")
  else hablar("Trabajo nuevo. Ve a " .. rec.nombre) end
end

function accionTrabajo()
  local tr = J.trabajo
  if not tr or not tr.listo then return end
  tr.listo = false
  if tr.tipo == "bomberos" then
    sonar("fuego")
    J.dinero = J.dinero + tr.paga
    sonar("dinero")
    hablar("Fuego apagado. Has ganado " .. tr.paga .. " pesos. Tu saldo es de " .. J.dinero .. " pesos.")
    J.trabajo = nil
    guardar()
    return
  end
  if tr.paradas and tr.paradas > 0 then
    sonar("recoger")
    J.dinero = J.dinero + tr.pagaParada
    tr.paradas = tr.paradas - 1
    if tr.paradas <= 0 then
      J.dinero = J.dinero + 20
      sonar("dinero")
      hablar("Ruta terminada. Has ganado " .. (tr.pagaParada * 3 + 20) .. " pesos en total. Tu saldo es de " .. J.dinero .. " pesos.")
      J.trabajo = nil
      guardar()
      return
    end
    local sig = lugarAleatorio()
    fijarObjetivoTrabajo(sig, tr.textoRec)
    hablar("Siguiente parada: " .. sig.nombre .. ". Quedan " .. tr.paradas .. ".")
    return
  end
  if tr.fase == 1 then
    sonar("recoger")
    tr.fase = 2
    local textoEnt = "ENTREGAR"
    if tr.tipo == "taxi" then textoEnt = "EL PASAJERO SE BAJA"
    elseif tr.tipo == "ambulancia" then textoEnt = "DEJAR AL HERIDO EN EL HOSPITAL"
    elseif tr.tipo == "vigilante" then textoEnt = "LLEVAR A LA COMISARÍA"
    elseif tr.tipo == "camion" then textoEnt = "ENTREGAR LA CARGA"
    elseif tr.tipo == "grua" then textoEnt = "DEJAR EN EL TALLER"
    elseif tr.tipo == "paqueteria" then textoEnt = "ENTREGAR EL PAQUETE"
    elseif tr.tipo == "mensajeria" then textoEnt = "ENTREGAR EL ENVÍO" end
    if tr.entrega then
      fijarObjetivoTrabajo(tr.entrega, textoEnt)
      hablar("Ahora lleva a " .. tr.entrega.nombre)
    else
      J.trabajo = nil
    end
    return
  end
  sonar("dinero")
  J.dinero = J.dinero + tr.paga
  hablar("Has ganado " .. tr.paga .. " pesos. Tu saldo es de " .. J.dinero .. " pesos.")
  J.trabajo = nil
  guardar()
end

function pedirAyuda(tipo)
  if J.ayuda then
    toast("La ayuda ya viene en camino")
    return
  end
  local ax = J.x + 300
  local ay = J.y
  if ax > anchoMapa() then ax = J.x - 300 end
  if ax < 0 then ax = 0 end
  J.ayuda = { tipo = tipo, x = ax, y = ay, estado = "viene" }
  J.ultimoAvisoAyuda = os.time()
  if tipo == "ambulancia" then
    sonar("sirena_ambulancia")
    hablar("La ambulancia viene en camino con la sirena.")
  elseif tipo == "grua" then
    hablar("La grúa viene en camino a recogerte.")
  elseif tipo == "taller" then
    hablar("El mecánico viene en su carro a repararte.")
  elseif tipo == "gasolina" then
    hablar("El mecánico viene con gasolina para ti.")
  end
end

function mostrarMenuAyuda()
  local dlg = LuaDialog(service)
  dlg.setTitle("MENÚ DE AYUDA")
  local d = nil
  local layout = {
    LinearLayout,
    orientation = "vertical",
    layout_width = "fill",
    layout_height = "wrap",
    padding = "16dp",
  }
  local opciones = {
    { "AMBULANCIA", "ambulancia" },
    { "GRÚA", "grua" },
    { "TALLER (mecánico)", "taller" },
    { "GASOLINA (mecánico)", "gasolina" },
  }
  for _, op in ipairs(opciones) do
    local etiqueta = op[1]
    local tipo = op[2]
    table.insert(layout, {
      Button,
      text = etiqueta,
      layout_width = "fill",
      layout_height = "wrap",
      layout_marginBottom = "6dp",
      onClick = function()
        pedirAyuda(tipo)
        if d then d.dismiss() end
      end,
    })
  end
  table.insert(layout, {
    Button,
    text = "CANCELAR AYUDA",
    layout_width = "fill",
    layout_height = "wrap",
    layout_marginBottom = "6dp",
    onClick = function()
      J.ayuda = nil
      hablar("Ayuda cancelada.")
      if d then d.dismiss() end
    end,
  })
  table.insert(layout, {
    Button,
    text = "CERRAR",
    layout_width = "fill",
    layout_height = "wrap",
    onClick = function()
      if d then d.dismiss() end
    end,
  })
  local sv = ScrollView(service)
  sv.addView(loadlayout(layout))
  dlg.setView(sv)
  d = dlg
  d.show()
  hablar("Menú de ayuda. Elige ambulancia, grúa, taller o gasolina.")
end

function mostrarMenuDestinos()
  local dlg = LuaDialog(service)
  dlg.setTitle("MENÚ DE DESTINOS")
  local d = nil
  local layout = {
    LinearLayout,
    orientation = "vertical",
    layout_width = "fill",
    layout_height = "wrap",
    padding = "16dp",
    {
      TextView,
      text = "MAPAS",
      textSize = "18sp",
      layout_width = "fill",
      layout_height = "wrap",
    },
  }
  for _, mp in ipairs(MAPAS) do
    local mm = mp
    table.insert(layout, {
      Button,
      text = mm.nombre,
      layout_width = "fill",
      layout_height = "wrap",
      layout_marginBottom = "4dp",
      onClick = function()
        local cx, cy
        if mm.ancho then cx, cy = 1200, 750 else cx, cy = (mm.nav - 1) * 45, (mm.nc - 1) * 45 end
        fijarDestino({ mapa = mm.id, x = cx, y = cy, nombre = "Mapa: " .. mm.nombre })
        if d then d.dismiss() end
      end,
    })
  end
  table.insert(layout, {
    TextView,
    text = "SERVICIOS CERCANOS",
    textSize = "18sp",
    layout_width = "fill",
    layout_height = "wrap",
    layout_marginTop = "8dp",
  })
  local servicios = {
    { "Gasolinera", function(l) return esGasolinera(l) end },
    { "Taller", function(l) return l.tipo == "taller" end },
    { "Concesionario", function(l) return l.tipo == "concesionario" end },
    { "Banco", function(l) return l.tipo == "banco" end },
    { "Hospital", function(l) return l.tipo == "hospital" end },
    { "Tienda", function(l) return l.tipo == "tienda" end },
    { "Farmacia", function(l) return l.tipo == "farmacia" end },
    { "Comisaría", function(l) return l.tipo == "comisaria" end },
  }
  for _, s in ipairs(servicios) do
    local etiqueta = s[1]
    local cond = s[2]
    local lug, dd = buscarLugar(cond, J.mapa)
    if lug then
      local ll = lug
      local ddx = dd
      table.insert(layout, {
        Button,
        text = etiqueta .. ": " .. ll.nombre .. " (" .. math.floor(ddx + 0.5) .. " m)",
        layout_width = "fill",
        layout_height = "wrap",
        layout_marginBottom = "4dp",
        onClick = function()
          local lx, ly = lugarXY(ll)
          fijarDestino({ mapa = ll.mapa, x = lx, y = ly, nombre = ll.nombre })
          if d then d.dismiss() end
        end,
      })
    end
  end
  table.insert(layout, {
    TextView,
    text = "LUGARES DE ESTE MAPA",
    textSize = "18sp",
    layout_width = "fill",
    layout_height = "wrap",
    layout_marginTop = "8dp",
  })
  for _, l in ipairs(lugaresMapa(J.mapa)) do
    local ll = l
    table.insert(layout, {
      Button,
      text = ll.nombre,
      layout_width = "fill",
      layout_height = "wrap",
      layout_marginBottom = "2dp",
      onClick = function()
        local lx, ly = lugarXY(ll)
        fijarDestino({ mapa = ll.mapa, x = lx, y = ly, nombre = ll.nombre })
        if d then d.dismiss() end
      end,
    })
  end
  local sv = ScrollView(service)
  sv.addView(loadlayout(layout))
  dlg.setView(sv)
  d = dlg
  d.show()
  hablar("Menú de destinos. Elige un mapa, un servicio o un lugar. Luego pulsa piloto automático.")
end

function repostar()
  local gas, dd = buscarLugar(function(l) return esGasolinera(l) end, J.mapa)
  if not gas or dd >= 45 then return end
  local falta = 50 - J.gas
  if falta <= 0.5 then
    hablar("El tanque ya está lleno.")
    return
  end
  local costo = math.ceil(falta * 1)
  if J.dinero >= costo then
    J.dinero = J.dinero - costo
    J.gas = 50
    J.sinGasAvisado = false
    sonar("repostar")
    hablar("Tanque lleno. Pagaste " .. costo .. " pesos. Te quedan " .. J.dinero .. " pesos.")
  else
    local litros = J.dinero
    J.gas = J.gas + litros
    J.dinero = 0
    sonar("repostar")
    hablar("Echaste " .. litros .. " litros con lo que tenías. Te quedaste sin dinero.")
  end
  guardar()
  actualizarHUD()
end

function reparar()
  local tal, dd = buscarLugar(function(l) return l.tipo == "taller" end, J.mapa)
  if not tal or dd >= 45 then return end
  if J.dano <= 0 then
    hablar("Tu carro no tiene daños.")
    return
  end
  if J.dinero >= 20 then
    J.dinero = J.dinero - 20
    J.dano = 0
    J.rotoAvisado = false
    sonar("reparar")
    hablar("Carro reparado. Pagaste 20 pesos. Te quedan " .. J.dinero .. " pesos.")
    guardar()
  else
    hablar("La reparación cuesta 20 pesos y no te alcanza. Llama al mecánico en el menú de ayuda, él viene gratis.")
  end
  actualizarHUD()
end

function iniciar()
  instalarSonidos()
  cargar()
  mostrarMenuPrincipal()
end

function onDestroy()
  J.enMarcha = false
  motorApagar()
  bucleAmb = pararBucle(bucleAmb)
  bucleMenu = pararBucle(bucleMenu)
end

iniciar()
